mapper.select:


    del_flag = '0'

        and device_code like concat('%', #{deviceCode}, '%')


        and device_name like concat('%', #{deviceName}, '%')


        and device_type = #{deviceType}


        and enterprise_id = #{enterpriseId}


        and device_status = #{deviceStatus}


        and auth_status = #{authStatus}


        and region_code like concat(#{regionCode}, '%')

    ${params.regionDataScope}
    ${params.enterpriseDataScope}

order by create_time desc, device_id desc
